import java.util.*;

public class CacheLokalnyVsWspolny {
    static class Instancja {
        final String nazwa; final Map<String, Integer> cache; final Map<String, Integer> baza;
        Instancja(String nazwa, Map<String, Integer> cache, Map<String, Integer> baza) {
            this.nazwa = nazwa; this.cache = cache; this.baza = baza;
        }
        int odczytaj(String id) {
            return cache.computeIfAbsent(id, baza::get);
        }
        void zmienCene(String id, int cena) {
            baza.put(id, cena);
            cache.put(id, cena);
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> baza = new HashMap<>(Map.of("p1", 100));
        Instancja a = new Instancja("A", new HashMap<>(), baza);
        Instancja b = new Instancja("B", new HashMap<>(), baza);
        a.odczytaj("p1");
        b.zmienCene("p1", 80);
        System.out.println("Lokalne: A=" + a.odczytaj("p1") + " B=" + b.odczytaj("p1")); // A=100 B=80

        Map<String, Integer> wspolny = new HashMap<>();   // 'Redis'
        baza.put("p1", 100);
        Instancja a2 = new Instancja("A", wspolny, baza);
        Instancja b2 = new Instancja("B", wspolny, baza);
        a2.odczytaj("p1");
        b2.zmienCene("p1", 80);
        System.out.println("Wspolny: A=" + a2.odczytaj("p1") + " B=" + b2.odczytaj("p1")); // A=80 B=80
    }
}

import java.util.*;

public class CacheAside {
    static Map<Integer, String> cache = new HashMap<>();
    static int hit, miss;

    static String zBazy(int id) throws InterruptedException {
        Thread.sleep(100);
        return "produkt-" + id;
    }

    static String pobierz(int id) throws InterruptedException {
        String w = cache.get(id);
        if (w != null) { hit++; return w; }
        miss++;
        w = zBazy(id);
        cache.put(id, w);
        return w;
    }

    public static void main(String[] args) throws Exception {
        long start = System.currentTimeMillis();
        for (int id : new int[]{1, 2, 3, 1, 2, 3, 1, 1, 2, 3}) pobierz(id);
        long czas = System.currentTimeMillis() - start;
        System.out.println("hit=" + hit + " miss=" + miss + " czas~" + czas + " ms");
        // hit=7 miss=3 czas~300 ms - baza odpytana 3 razy zamiast 10
    }
}

import java.util.*;

public class CacheZTtl {
    record Wpis(String wartosc, long wygasaO) {}
    static Map<Integer, Wpis> cache = new HashMap<>();
    static int zapytaniaDoBazy;
    static final long TTL = 300;

    static String pobierz(int id, long teraz) {
        Wpis w = cache.get(id);
        if (w != null && w.wygasaO() > teraz) return w.wartosc();
        zapytaniaDoBazy++;
        String wartosc = "produkt-" + id + "@" + teraz;
        cache.put(id, new Wpis(wartosc, teraz + TTL));
        return wartosc;
    }

    public static void main(String[] args) {
        System.out.println(pobierz(1, 0));    // produkt-1@0 (miss)
        System.out.println(pobierz(1, 299));  // produkt-1@0 (hit)
        System.out.println(pobierz(1, 300));  // produkt-1@300 (wygasl -> baza)
        System.out.println("zapytania do bazy: " + zapytaniaDoBazy); // 2
    }
}
To odpowiednik SET klucz wartosc EX 300 w Redis: po wygaśnięciu klucz znika, a następny odczyt odświeża dane z bazy.

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Stampede {
    static AtomicInteger wywolania = new AtomicInteger();

    static String baza(String k) {
        wywolania.incrementAndGet();
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "wartosc-" + k;
    }

    static int uruchom(boolean computeIfAbsent) throws Exception {
        wywolania.set(0);
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        ExecutorService ex = Executors.newFixedThreadPool(20);
        CountDownLatch start = new CountDownLatch(1);
        for (int i = 0; i < 20; i++) {
            ex.submit(() -> {
                start.await();
                if (computeIfAbsent) return cache.computeIfAbsent("top", Stampede::baza);
                String w = cache.get("top");
                if (w == null) { w = baza("top"); cache.put("top", w); }
                return w;
            });
        }
        start.countDown();
        ex.shutdown();
        ex.awaitTermination(5, TimeUnit.SECONDS);
        return wywolania.get();
    }

    public static void main(String[] args) throws Exception {
        System.out.println("get+put: " + uruchom(false));          // zwykle 20 (lub blisko)
        System.out.println("computeIfAbsent: " + uruchom(true));   // 1
    }
}
W rozproszonym systemie (wiele instancji) to samo osiąga się blokadą w Redis (SET ... NX EX).

